// Synchronize file contents to storage
// Blocks until transfer is complete

int fd_target;  // Open file descriptor

// fsync: Flushes all modified data AND metadata
int sync_status = fsync(fd_target);

if (sync_status == -1) {
    // Check errno for EBADF (invalid fd), EINTR, EIO
    // handle_error();
}

// fdatasync: Flushes data, and only metadata necessary
// for subsequent retrieval (often faster).
int data_sync_status = fdatasync(fd_target);

if (data_sync_status == -1) {
    // handle_error();
}
